from pathlib import Path
p=Path('dist/index.html')
s=p.read_text(encoding='utf-8').replace('<script src="snapshot.js" defer></script>','<script src="snapshot.js" defer></script><script src="import.js" defer></script>')
section='''<section class="workspace import-section"><p class="eyebrow" data-en="USE YOUR OWN DATA" data-mr="तुमची स्वतःची माहिती वापरा">USE YOUR OWN DATA</p><h2 data-en="Bring a mandi price CSV." data-mr="बाजारभावाची CSV फाइल वापरा.">Bring a mandi price CSV.</h2><p data-en="Choose a downloaded CSV with Nashik onion records. It stays on this device. The file is not refreshed automatically; verify its source, date and units." data-mr="नाशिक कांद्याच्या नोंदी असलेली CSV फाइल निवडा. फाइल या उपकरणावरच राहते. स्रोत आणि दिनांक तपासा.">Choose a downloaded CSV with Nashik onion records. It stays on this device. The file is not refreshed automatically; verify its source, date and units.</p><p class="fine" data-en="Required headers: State, District, Market, Commodity, Arrival_Date, Modal_Price; Variety and Grade are needed to compare. Dates: DD/MM/YYYY. Maximum file size: 5 MB." data-mr="आवश्यक स्तंभ: State, District, Market, Commodity, Arrival_Date, Modal_Price; तुलनेसाठी Variety आणि Grade. दिनांक DD/MM/YYYY. कमाल ५ MB.">Required headers: State, District, Market, Commodity, Arrival_Date, Modal_Price; Variety and Grade are needed to compare. Dates: DD/MM/YYYY. Maximum file size: 5 MB.</p><label><span data-en="Choose CSV file" data-mr="CSV फाइल निवडा">Choose CSV file</span><input id="csv-file" type="file" accept=".csv,text/csv"></label><p id="csv-message" aria-live="polite"></p><div id="csv-results" hidden><label><span data-en="First market record" data-mr="पहिली बाजार नोंद">First market record</span><select id="csv-rows"></select></label><label><span data-en="Second market record" data-mr="दुसरी बाजार नोंद">Second market record</span><select id="csv-rows-b"></select></label><button type="button" id="csv-load" class="quiet" data-en="Use these records" data-mr="या नोंदी वापरा">Use these records</button></div></section>'''
